{
  "name": "串口通信设备",
  "name_en": "Serial Communication Device",
  "manufacturer": "",
  "description": "一种通过串行端口进行数据收发的实验设备或仪器接口，常见于带 UART、RS-232 或 USB 虚拟串口的实验仪器。它可用于实验室中与上位机交换文本或原始字节数据，并配置波特率、校验位、数据位、停止位以及 RTS/DTR 等串口通信参数。",
  "description_en": "A laboratory device or instrument interface that communicates through a serial port, commonly using UART, RS-232, or a USB virtual COM port. It is used in labs to exchange text or raw byte data with a host computer and to configure serial communication parameters such as baud rate, parity, data bits, stop bits, and RTS/DTR control lines.",
  "tag_hints": [
    "serial communication",
    "UART",
    "RS-232",
    "USB virtual COM port",
    "instrument communication",
    "baud rate configuration",
    "RTS/DTR control"
  ],
  "actions": [
    {
      "action_name": "auto-readBytes",
      "description": "读取串口接收到的原始字节数据。",
      "description_en": "Read raw byte data received from the serial port."
    },
    {
      "action_name": "auto-readText",
      "description": "读取串口接收到的文本数据。",
      "description_en": "Read text data received from the serial port."
    },
    {
      "action_name": "auto-write",
      "description": "向串口写入数据。",
      "description_en": "Write data to the serial port."
    },
    {
      "action_name": "auto-setControlLineState",
      "description": "设置串口 RTS 和 DTR 控制线状态。",
      "description_en": "Set the RTS and DTR control line states of the serial port."
    },
    {
      "action_name": "auto-setLineCoding",
      "description": "设置串口线路编码参数，如波特率、校验位、数据位和停止位。",
      "description_en": "Set the serial line coding parameters such as baud rate, parity, data bits, and stop bits."
    },
    {
      "action_name": "auto-getLineCoding",
      "description": "获取串口线路编码参数。",
      "description_en": "Get the serial line coding parameters."
    }
  ]
}

